from pathlib import Path
from lupa import LuaRuntime

def make_game(source=Path('outputs/DMC5CharacterSwitch/dmc5_switch_runtime.lua')):
    lua=LuaRuntime()
    lua.execute("\nhooks={};storage={};mode=0;mission=7;nativeID=0;paused=false\nthread={get_hook_storage=function()return storage end}\nplayers={}\nfor _,id in ipairs({0,1,2,4})do\n players[id]={id=id,call=function(self,n)\n  if n=='get_playerID'then return self.id end\n  if n=='get_isEventMove'then return self.event or false end\n  if n=='get_isEventRun'then return self.running or false end\n  error(n)\n end}\nend\nactive=players[0]\nfunction newSetting(id)\n return {id=id,call=function(self,n,v)\n  if n=='get_ControllPlayerID'then return self.id end\n  assert(n=='set_ControllPlayerID');self.id=v\n end}\nend\nsetting=newSetting(0)\ngm={call=function(_,n)\n if n=='get_gameMode'then return mode end\n if n=='get_missionNo'then return mission end\n if n=='findManualPlayerID'then return nativeID end\n return paused\nend}\nsettingManager={call=function(_,n)if n=='get_Setting'then return setting end;assert(n=='get_isEntered');return true end}\nmanager={call=function(_,n,id)\n if n=='getPlayerByID'then return players[id]end\n if n=='get_manualPlayer'then return active end\n assert(n=='updateManualPlayer')\n local h=hooks['updateManualPlayer'];if h then h[1]({[2]=manager})end\n -- This is the native lookup called on EVERY PlayerManager.doUpdate.\n active=players[setting.id]\n if h then assert(h[2](123)==123)end\nend}\nsdk={find_type_definition=function()return {get_method=function(_,n)return n end}end,\n hook=function(n,pre,post)hooks[n]={pre,post}end,to_managed_object=function(v)return v end,\n get_managed_singleton=function(n)\n  if n=='app.GameManager'then return gm end\n  assert(n=='app.MissionSettingManager');return settingManager\n end}\ndmc5_switch_loader={manager=manager,generation=1,sceneMode=0,storyMission=7}\n-- Native isInterferenceAreaMaster compares source 4/8/16 to Setting.PlayerInfo.\nfunction spawn(route)\n local masks={[0]=4,[1]=8,[2]=16,[4]=4}\n return {puppet=route~=masks[setting.id]}\nend\n")
    runtime=lua.execute(source.read_text())
    lua.globals().R=runtime
    return lua
